local PlantTyingTwistMaker = {}
local PRODUCTS = {
    iron_planttyingtwist = { name = "Železni veza za rastline", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni veza za rastline za vrtnarje." },
    bronze_planttyingtwist = { name = "Bronast veza za rastline", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast veza za rastline za vrtnarje." },
    silver_planttyingtwist = { name = "Srebrn veza za rastline", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn veza za rastline za vrtnarje." },
    gilded_planttyingtwist = { name = "Pozlačen veza za rastline", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen veza za rastline za vrtnarje." },
    jewel_set_planttyingtwist = { name = "Draguljast veza za rastline", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast veza za rastline za vrtnarje." },
    royal_sovereign_planttyingtwist = { name = "Kraljevski suveren veza za rastline", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren veza za rastline z biseri za krono." },
}
local BUILDINGS = {
    planttyingtwist_workshop = { name = "Planttyingtwist delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    planttyingtwist_house = { name = "Planttyingtwist hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_planttyingtwist_atelier = { name = "Mojstrski planttyingtwist atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_planttyingtwist_palace = { name = "Suverena planttyingtwist palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PlantTyingTwistMaker.ironStock=10; PlantTyingTwistMaker.bronzeStock=8; PlantTyingTwistMaker.woodStock=14; PlantTyingTwistMaker.leatherStock=14; PlantTyingTwistMaker.silverStock=8; PlantTyingTwistMaker.goldStock=6; PlantTyingTwistMaker.jewelStock=4; PlantTyingTwistMaker.pearlStock=4
PlantTyingTwistMaker.productStock = {}; PlantTyingTwistMaker.buildings = {}; PlantTyingTwistMaker.maker = nil; PlantTyingTwistMaker.activeMaking = {}; PlantTyingTwistMaker.totalProducts = 0; PlantTyingTwistMaker.dayTimer = 0
function PlantTyingTwistMaker.init() PlantTyingTwistMaker.ironStock=10; PlantTyingTwistMaker.bronzeStock=8; PlantTyingTwistMaker.woodStock=14; PlantTyingTwistMaker.leatherStock=14; PlantTyingTwistMaker.silverStock=8; PlantTyingTwistMaker.goldStock=6; PlantTyingTwistMaker.jewelStock=4; PlantTyingTwistMaker.pearlStock=4; PlantTyingTwistMaker.productStock={}; PlantTyingTwistMaker.buildings={}; PlantTyingTwistMaker.maker=nil; PlantTyingTwistMaker.activeMaking={}; PlantTyingTwistMaker.totalProducts=0; PlantTyingTwistMaker.dayTimer=0; print("[PlantTyingTwistMaker] Royal Plant Tying Twist Maker System initialized (6 products, 4 buildings)") end
function PlantTyingTwistMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlantTyingTwistMaker.maker={name=n or ("Vezar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vezar najet: %s (spretnost: %d)",PlantTyingTwistMaker.maker.name,s),"success") end; return true end
function PlantTyingTwistMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlantTyingTwistMaker.build(id) local ok,e=PlantTyingTwistMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlantTyingTwistMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlantTyingTwistMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlantTyingTwistMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlantTyingTwistMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PlantTyingTwistMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PlantTyingTwistMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PlantTyingTwistMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PlantTyingTwistMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PlantTyingTwistMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlantTyingTwistMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlantTyingTwistMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlantTyingTwistMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlantTyingTwistMaker.buildings==0 then return false,"Potrebna vezna delavnica" end; if not PlantTyingTwistMaker.maker then return false,"Potreben vezar" end; return true end
function PlantTyingTwistMaker.make(pt,qty) qty=qty or 1; local ok,e=PlantTyingTwistMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PlantTyingTwistMaker.ironStock=PlantTyingTwistMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PlantTyingTwistMaker.bronzeStock=PlantTyingTwistMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PlantTyingTwistMaker.woodStock=PlantTyingTwistMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PlantTyingTwistMaker.leatherStock=PlantTyingTwistMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PlantTyingTwistMaker.silverStock=PlantTyingTwistMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlantTyingTwistMaker.goldStock=PlantTyingTwistMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlantTyingTwistMaker.jewelStock=PlantTyingTwistMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlantTyingTwistMaker.pearlStock=PlantTyingTwistMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlantTyingTwistMaker.maker then t=math.max(1,t-math.floor(PlantTyingTwistMaker.maker.skill/13)) end; table.insert(PlantTyingTwistMaker.activeMaking,{id="planttyingtwist_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlantTyingTwistMaker.completeMaking(m) local q=1.0+(PlantTyingTwistMaker.getQualityBonus()/100); if PlantTyingTwistMaker.maker then q=q+(PlantTyingTwistMaker.maker.skill/140) end; q=math.min(2.5,q); PlantTyingTwistMaker.productStock[m.productType]=(PlantTyingTwistMaker.productStock[m.productType] or 0)+m.quantity; PlantTyingTwistMaker.totalProducts=PlantTyingTwistMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlantTyingTwistMaker.maker then PlantTyingTwistMaker.maker.itemsMade=PlantTyingTwistMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlantTyingTwistMaker.maker.skill=math.min(100,PlantTyingTwistMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vez izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"planttyingtwist.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PlantTyingTwistMaker.update(dt) if not _G.state then return end; PlantTyingTwistMaker.dayTimer=PlantTyingTwistMaker.dayTimer+dt; if PlantTyingTwistMaker.dayTimer>=30 then PlantTyingTwistMaker.dayTimer=0; for i=#PlantTyingTwistMaker.activeMaking,1,-1 do local m=PlantTyingTwistMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlantTyingTwistMaker.completeMaking(m); table.remove(PlantTyingTwistMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlantTyingTwistMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlantTyingTwistMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlantTyingTwistMaker.getStats() return {ironStock=PlantTyingTwistMaker.ironStock,bronzeStock=PlantTyingTwistMaker.bronzeStock,woodStock=PlantTyingTwistMaker.woodStock,leatherStock=PlantTyingTwistMaker.leatherStock,silverStock=PlantTyingTwistMaker.silverStock,goldStock=PlantTyingTwistMaker.goldStock,jewelStock=PlantTyingTwistMaker.jewelStock,pearlStock=PlantTyingTwistMaker.pearlStock,productStock=PlantTyingTwistMaker.productStock,numBuildings=#PlantTyingTwistMaker.buildings,hasMaker=PlantTyingTwistMaker.maker~=nil,makerName=PlantTyingTwistMaker.maker and PlantTyingTwistMaker.maker.name or "—",makerSkill=PlantTyingTwistMaker.maker and PlantTyingTwistMaker.maker.skill or 0,activeMaking=#PlantTyingTwistMaker.activeMaking,totalProducts=PlantTyingTwistMaker.totalProducts} end
return PlantTyingTwistMaker
